static void _glowDrawBeam(const SVECTOR worldPoints[2], s32 radiusScale, s32 startAngle, s32 packedColor);
static void _glowDrawTintedDisc(const SVECTOR* worldPoint, s32 radiusScale, s32 packedColor);

/// Draws the armory lock's flickering green unlocked or red locked indicator.
///
/// `radiusScale` is a signed 16-bit perspective scale. The disc's outer pixel
/// radius is `radiusScale * 64 / (camera Z / 4 + 1)`; two blades reach twice that.
/// Requires composed current-view matrices, scratch space for
/// `GlowCentreRadiiScratch`, and frame packet/ordering-table space for twenty
/// additive quads and their blend commands. Packets live until GPU completion.
static inline void _shelterB1ArmoryDrawLockGlow(s16 radiusScale)
{
    // RGB nibbles give a 192-level primary; the high nibble adds 32 to every
    // channel on odd animation frames.
    enum {
        SHELTER_B1_ARMORY_UNLOCKED_GLOW_COLOR = 0x50C0,
        SHELTER_B1_ARMORY_LOCKED_GLOW_COLOR   = 0x5C00,
    };

    if (gameFlagGetNibble(GAME_FLAG_SHELTER_B1_ARMORY_UNLOCKED) != 0) {
        _glowDrawTintedDisc(&_gShelterB1ArmoryGlowWorldPoints.unlockedIndicator, radiusScale, SHELTER_B1_ARMORY_UNLOCKED_GLOW_COLOR);
    } else {
        _glowDrawTintedDisc(&_gShelterB1ArmoryGlowWorldPoints.lockedIndicator, radiusScale, SHELTER_B1_ARMORY_LOCKED_GLOW_COLOR);
    }
}

void shelterB1ArmoryDrawGlowsTask(Task* unusedTask)
{
    enum {
        // Pixel radius is the scale * 64 / (camera Z / 4), biased by one for lock glows.
        SHELTER_B1_ARMORY_BEAM_RADIUS_SCALE       = 0x200,
        SHELTER_B1_ARMORY_CYAN_DISC_RADIUS_SCALE  = 0x300,
        SHELTER_B1_ARMORY_VIEW3_LOCK_RADIUS_SCALE = 0x100,
        SHELTER_B1_ARMORY_VIEW9_LOCK_RADIUS_SCALE = 0x60,
        // Red-byte and green/blue-bit factors multiplying the 32/40 frame intensity.
        SHELTER_B1_ARMORY_GREEN_BEAM_COLOR = 0x10,
        SHELTER_B1_ARMORY_WHITE_BEAM_COLOR = 0x111,
        SHELTER_B1_ARMORY_CYAN_DISC_COLOR  = 0x11,
    };
    u8 mappedViewIndex;

    // Draw only the glows selected for this mapped camera view.
    mappedViewIndex = viewGetMappedIndex();
    switch (mappedViewIndex) {
        case 2:
            _glowDrawBeam(&_gShelterB1ArmoryGlowWorldPoints.greenBeam[0], SHELTER_B1_ARMORY_BEAM_RADIUS_SCALE, 0, SHELTER_B1_ARMORY_GREEN_BEAM_COLOR);
            _glowDrawBeam(&_gShelterB1ArmoryGlowWorldPoints.whiteBeams[0][0], SHELTER_B1_ARMORY_BEAM_RADIUS_SCALE, GLOW_HALF_TURN, SHELTER_B1_ARMORY_WHITE_BEAM_COLOR);
            _glowDrawBeam(&_gShelterB1ArmoryGlowWorldPoints.whiteBeams[1][0], SHELTER_B1_ARMORY_BEAM_RADIUS_SCALE, GLOW_HALF_TURN, SHELTER_B1_ARMORY_WHITE_BEAM_COLOR);
            break;
        case 3:
            _glowDrawBeam(&_gShelterB1ArmoryGlowWorldPoints.whiteBeams[2][0], SHELTER_B1_ARMORY_BEAM_RADIUS_SCALE, 0, SHELTER_B1_ARMORY_WHITE_BEAM_COLOR);
            _glowDrawBitDisc(&_gShelterB1ArmoryGlowWorldPoints.cyanDisc, SHELTER_B1_ARMORY_CYAN_DISC_RADIUS_SCALE, SHELTER_B1_ARMORY_CYAN_DISC_COLOR);
            _shelterB1ArmoryDrawLockGlow(SHELTER_B1_ARMORY_VIEW3_LOCK_RADIUS_SCALE);
            break;
        case 8:
            _glowDrawBeam(&_gShelterB1ArmoryGlowWorldPoints.whiteBeams[0][0], SHELTER_B1_ARMORY_BEAM_RADIUS_SCALE, GLOW_HALF_TURN, SHELTER_B1_ARMORY_WHITE_BEAM_COLOR);
            break;
        case 9:
            _shelterB1ArmoryDrawLockGlow(SHELTER_B1_ARMORY_VIEW9_LOCK_RADIUS_SCALE);
            break;
        case 13:
            _glowDrawBitDisc(&_gShelterB1ArmoryGlowWorldPoints.cyanDisc, SHELTER_B1_ARMORY_CYAN_DISC_RADIUS_SCALE, SHELTER_B1_ARMORY_CYAN_DISC_COLOR);
            break;
    }
}

